import React, { useState, useEffect, useCallback } from 'react';
import { Film, Inbox, X } from 'lucide-react';
import { lockBodyScroll } from '../utils/modalBehavior';
import { blocksHaveConditions, describeCondition, genresInSequence, needsPlaybackInfo } from '../utils/sequenceConditions';
import { AUDIO_FORMATS } from '../utils/audioFormats';
// eslint-disable-next-line no-unused-vars
import SequenceTimeline from './SequenceTimeline';
// eslint-disable-next-line no-unused-vars
import SequenceStats from './SequenceStats';

// Human names for block types, used when telling the viewer which block had
// nothing to play.
const BLOCK_LABELS = {
  preroll: 'Fixed preroll',
  fixed: 'Fixed preroll',
  random: 'Category block',
  sequential: 'Category block',
  nexup_trailers: 'NeX-Up trailers',
  library_trailers: 'Library trailers',
  coming_soon_list: 'Coming Soon list',
  dynamic_preroll: 'Generated preroll',
  separator: 'Pause / separator',
};

// Stands in for a block whose condition is not met and has no alternative, so
// later blocks keep their positions and it isn't reported as "nothing to play".
const CONDITION_SKIPPED = '__condition_skipped';

/**
 * SequencePreviewModal - Full-screen preview modal with playback simulator
 * Shows timeline visualization, statistics, and simulates sequence playback
 * 
 * Props:
 * - isOpen: Boolean - whether modal is visible
 * - onClose: Function - callback to close modal
 * - blocks: Array of sequence blocks
 * - categories: Array of available categories
 * - prerolls: Array of all prerolls
 * - sequenceName: String - name of the sequence
 * - apiUrl: Function - API URL builder
 */
const SequencePreviewModal = ({ isOpen, onClose, blocks = [], categories = [], prerolls = [], sequenceName = 'Untitled Sequence', apiUrl }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentBlockIndex, setCurrentBlockIndex] = useState(-1);
  const [currentPrerollIndex, setCurrentPrerollIndex] = useState(0);
  const [playbackProgress, setPlaybackProgress] = useState(0);
  const [expandedBlocks, setExpandedBlocks] = useState(new Set());
  const [playlist, setPlaylist] = useState([]);
  // Blocks that produced nothing to play. A block that resolves empty used
  // to vanish from the preview with no trace, renumbering the blocks after
  // it, so a three-block sequence silently played as two.
  const [skippedBlocks, setSkippedBlocks] = useState([]);
  // Blocks the Advanced-mode conditions replaced or left out for this preview
  const [conditionNotes, setConditionNotes] = useState([]);
  // Genre to preview a genre-conditioned sequence as; '' is "unknown", which
  // is what Plex always is.
  const [previewGenre, setPreviewGenre] = useState('');
  const [previewAudio, setPreviewAudio] = useState('');
  const hasAudioRules = blocks.some(block => block.condition?.rules?.some(rule => rule.kind === 'audio_format'));
  const sequenceGenres = genresInSequence(blocks);
  const videoRef = React.useRef(null);
  const overlayRef = React.useRef(null);
  const isTransitioningRef = React.useRef(false);
  const expectedIndexRef = React.useRef(0);
  // Snapshot props at modal-open time so background refetches don't rebuild the playlist
  const snapshotRef = React.useRef({ prerolls: [], categories: [], blocks: [] });
  const [modalOpenCounter, setModalOpenCounter] = useState(0);

  // Get preroll details for a block (uses snapshot to avoid mid-playback changes)
  const getBlockPrerolls = useCallback((block, snapshotPrerolls) => {
    const prs = snapshotPrerolls;
    if (block.type === 'preroll') {
      const preroll = prs.find((p) => p.id === block.preroll_id);
      return preroll ? [preroll] : [];
    } else if (block.type === 'fixed') {
      // Fixed block with specific preroll IDs
      if (!block.preroll_ids || block.preroll_ids.length === 0) return [];
      return block.preroll_ids
        .map(id => prs.find(p => p.id === id))
        .filter(Boolean);
    } else if (block.type === 'random' || block.type === 'sequential') {
      // Match the backend's category-resolution rule: a preroll belongs to a
      // category via either the legacy category_id column OR the m2m categories
      // relationship. Pre-v1.13.2 we only checked category_id, so any preroll
      // imported / re-tagged after the m2m migration was invisible to the
      // sequence preview (skipped the block entirely).
      return prs.filter((p) =>
        p.file_exists !== false &&
        (p.category_id === block.category_id ||
         (Array.isArray(p.categories) && p.categories.some(c => c.id === block.category_id)))
      );
    } else if (block.type === 'queue') {
      return []; // Queue items would be dynamic
    } else if (block.type === 'sequence') {
      return []; // Nested sequence
    }
    return [];
  }, []);

  // Snapshot props when modal opens, increment counter to trigger playlist build once
  useEffect(() => {
    if (isOpen) {
      snapshotRef.current = { prerolls: [...prerolls], categories: [...categories], blocks: [...blocks] };
      setModalOpenCounter(c => c + 1);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen]);

  // Keep the full-screen player consistent with the other dialogs: Escape is
  // always a reliable way out, including before playback has started.
  useEffect(() => {
    if (!isOpen) return undefined;
    const releaseScrollLock = lockBodyScroll();
    const handleKeyDown = (event) => {
      if (event.key !== 'Escape') return;
      if (document.querySelector('.nx-dialog-overlay')) return;
      const overlays = Array.from(document.querySelectorAll('.nx-modal-overlay'))
        .filter(node => node.style.pointerEvents !== 'none');
      if (overlays[overlays.length - 1] !== overlayRef.current) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      onClose();
    };
    document.addEventListener('keydown', handleKeyDown);
    return () => {
      releaseScrollLock();
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen, onClose]);

  // Build the playlist ONCE when the modal opens (keyed off modalOpenCounter)
  useEffect(() => {
    if (!isOpen) {
      setIsPlaying(false);
      setCurrentBlockIndex(-1);
      setCurrentPrerollIndex(0);
      setPlaybackProgress(0);
      setPlaylist([]);
      setSkippedBlocks([]);
      setConditionNotes([]);
      return;
    }

    // Everything below builds the playlist for one set of blocks. When the
    // sequence has conditions, the backend first says what each slot would
    // play right now, and the playlist is built from that instead.
    const buildPlaylist = (snap) => {
      const newBlockTypes = ['nexup_trailers', 'library_trailers', 'coming_soon_list', 'dynamic_preroll'];
      const blocksNeedingResolve = snap.blocks
        .map((b, i) => ({ ...b, _idx: i }))
        .filter(b => newBlockTypes.includes(b.type));

      // Build local playlist items first (random, fixed, etc.)
      const buildLocalItems = () => {
        const items = [];
        snap.blocks.forEach((block, blockIndex) => {
          if (newBlockTypes.includes(block.type)) {
            // Placeholder — will be filled from backend resolve
            return;
          }
          const blockPrerolls = getBlockPrerolls(block, snap.prerolls);
          if (block.type === 'random' && blockPrerolls.length > 0) {
            const count = Math.max(1, Math.min(block.count || 1, blockPrerolls.length));
            const shuffled = [...blockPrerolls].sort(() => Math.random() - 0.5);
            shuffled.slice(0, count).forEach(preroll => {
              items.push({ blockIndex, preroll, blockType: 'random' });
            });
          } else if (block.type === 'sequential' && blockPrerolls.length > 0) {
            items.push({ blockIndex, preroll: blockPrerolls[0], blockType: 'sequential' });
          } else if (block.type === 'preroll') {
            const preroll = snap.prerolls.find(p => p.id === block.preroll_id);
            if (preroll) {
              items.push({ blockIndex, preroll, blockType: 'preroll' });
            }
          } else if (block.type === 'fixed' && block.preroll_ids) {
            block.preroll_ids.forEach(prerollId => {
              const preroll = snap.prerolls.find(p => p.id === prerollId);
              if (preroll) {
                items.push({ blockIndex, preroll, blockType: 'fixed' });
              }
            });
          }
        });
        return items;
      };

      // Any block with no items is reported rather than silently dropped.
      const noteSkipped = (items) => {
        const played = new Set(items.map(i => i.blockIndex));
        setSkippedBlocks(
          snap.blocks
            .map((b, i) => ({ block: b, index: i }))
            .filter(({ block, index }) => !played.has(index) && block.type !== CONDITION_SKIPPED)
            .map(({ block, index }) => ({
              index,
              label: block.label || BLOCK_LABELS[block.type] || 'Sequence block',
              type: block.type,
            }))
        );
        return items;
      };

      if (blocksNeedingResolve.length > 0) {
        // Resolve new block types via backend
        let active = true;
        const controller = new AbortController();
        fetch('/sequences/resolve-preview-blocks', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(blocksNeedingResolve),
          signal: controller.signal,
        })
          .then(res => {
            if (!res.ok) throw new Error(`Preview resolution failed (${res.status})`);
            return res.json();
          })
          .then(data => {
            if (!active) return;
            const localItems = buildLocalItems();
            // Merge resolved items at the correct block positions
            const resolvedByIdx = {};
            (data.blocks || []).forEach((result, i) => {
              const origIdx = blocksNeedingResolve[i]._idx;
              resolvedByIdx[origIdx] = (result.items || []).map(item => ({
                blockIndex: origIdx,
                directUrl: item.url,
                title: item.title,
                blockType: snap.blocks[origIdx].type,
                preroll: null
              }));
            });
            // Build final ordered playlist
            const finalPlaylist = [];
            let localPointer = 0;
            snap.blocks.forEach((block, blockIndex) => {
              if (resolvedByIdx[blockIndex]) {
                finalPlaylist.push(...resolvedByIdx[blockIndex]);
              } else {
                // Add all local items for this blockIndex
                while (localPointer < localItems.length && localItems[localPointer].blockIndex === blockIndex) {
                  finalPlaylist.push(localItems[localPointer]);
                  localPointer++;
                }
              }
            });
            // Append any remaining local items
            while (localPointer < localItems.length) {
              finalPlaylist.push(localItems[localPointer]);
              localPointer++;
            }
            setPlaylist(noteSkipped(finalPlaylist));
          })
          .catch((error) => {
            if (!active || error.name === 'AbortError') return;
            // Fallback: just use local items
            setPlaylist(noteSkipped(buildLocalItems()));
          });
        return () => {
          active = false;
          controller.abort();
        };
      } else {
        setPlaylist(noteSkipped(buildLocalItems()));
      }
      return undefined;
    };

    const original = snapshotRef.current;
    if (!blocksHaveConditions(original.blocks)) {
      setConditionNotes([]);
      return buildPlaylist(original);
    }

    let active = true;
    let innerCleanup;
    const controller = new AbortController();
    const params = new URLSearchParams();
    if (previewGenre) params.set('genres', previewGenre);
    if (previewAudio) params.set('audio_format', previewAudio);
    const genreQuery = params.size ? `?${params}` : '';
    fetch(`/sequences/evaluate-conditions${genreQuery}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      // eslint-disable-next-line no-unused-vars
      body: JSON.stringify(original.blocks.map(({ id, ...block }) => block)),
      signal: controller.signal,
    })
      .then(res => {
        if (!res.ok) throw new Error(`Condition check failed (${res.status})`);
        return res.json();
      })
      .then(data => {
        if (!active) return;
        const results = data.blocks || [];
        const notes = [];
        const blocks = original.blocks.map((block, i) => {
          const result = results[i];
          if (result && result.outcome === 'plays' && block.condition) {
            notes.push({
              index: i,
              label: block.label || BLOCK_LABELS[block.type] || 'Sequence block',
              outcome: 'plays',
              condition: block.condition,
            });
          }
          if (!result || result.outcome === 'plays') return block;
          notes.push({
            index: i,
            label: block.label || BLOCK_LABELS[block.type] || 'Sequence block',
            outcome: result.outcome,
            condition: block.condition,
          });
          if (result.outcome === 'skipped' || !result.block) return { id: block.id, type: CONDITION_SKIPPED };
          return { ...result.block, id: block.id };
        });
        setConditionNotes(notes);
        innerCleanup = buildPlaylist({ ...original, blocks });
      })
      .catch(error => {
        if (!active || error.name === 'AbortError') return;
        // Can't ask the server: preview every block as written.
        setConditionNotes([]);
        innerCleanup = buildPlaylist(original);
      });
    return () => {
      active = false;
      controller.abort();
      if (innerCleanup) innerCleanup();
    };
  }, [isOpen, modalOpenCounter, getBlockPrerolls, previewGenre, previewAudio]);

  // Start playback
  const startPlayback = () => {
    if (playlist.length === 0) return;
    isTransitioningRef.current = false;
    expectedIndexRef.current = 0;
    setIsPlaying(true);
    setCurrentPrerollIndex(0);
    setCurrentBlockIndex(playlist[0].blockIndex);
    setPlaybackProgress(0);
  };

  // Stop playback
  const stopPlayback = () => {
    isTransitioningRef.current = false;
    setIsPlaying(false);
    setCurrentBlockIndex(-1);
    setCurrentPrerollIndex(0);
    setPlaybackProgress(0);
    if (videoRef.current) {
      videoRef.current.pause();
      videoRef.current.currentTime = 0;
    }
  };

  // Helper function to get video URL for a preroll.
  // v1.13.18: stream by preroll ID instead of reconstructing a category-folder URL.
  // The old `static/prerolls/{category}/{filename}` pattern fell back to "unknown" for
  // uncategorized prerolls and 404'd. That's the user-reported "sequence preview
  // doesn't play the final preroll" — if the last item's category resolution failed,
  // handleVideoError would silently advance past the end of the playlist. Mirrors
  // the PREVIEW-1 fix already applied in App.js and main.py.
  const getVideoUrl = (preroll) => {
    if (!preroll || !apiUrl) return '';
    if (preroll.id) return apiUrl(`prerolls/${preroll.id}/video`);
    // Last-resort fallback for legacy items without an id — unlikely but safe.
    let categoryName = 'unknown';
    if (preroll.category && preroll.category.name) {
      categoryName = preroll.category.name;
    } else if (preroll.category_id) {
      const category = snapshotRef.current.categories.find(c => c.id === preroll.category_id);
      if (category) categoryName = category.name;
    }
    return apiUrl(`static/prerolls/${encodeURIComponent(categoryName)}/${encodeURIComponent(preroll.filename)}`);
  };

  // Handle video ended - move to next preroll
  const handleVideoEnded = () => {
    // Ignore if we're in the middle of a source transition
    if (isTransitioningRef.current) return;
    const nextIndex = currentPrerollIndex + 1;
    if (nextIndex < playlist.length) {
      expectedIndexRef.current = nextIndex;
      setCurrentPrerollIndex(nextIndex);
      setCurrentBlockIndex(playlist[nextIndex].blockIndex);
      setPlaybackProgress((nextIndex / playlist.length) * 100);
    } else {
      // Playback complete
      setIsPlaying(false);
      setCurrentBlockIndex(-1);
      setPlaybackProgress(100);
    }
  };

  // Handle video error - skip to next preroll (e.g. 404 / missing file)
  const handleVideoError = () => {
    // Ignore abort errors that fire during normal source transitions
    const error = videoRef.current?.error;
    if (!error || error.code === 1 /* MEDIA_ERR_ABORTED */) return;
    // Also ignore errors during active source transitions
    if (isTransitioningRef.current) return;
    const nextIndex = currentPrerollIndex + 1;
    if (nextIndex < playlist.length) {
      expectedIndexRef.current = nextIndex;
      setCurrentPrerollIndex(nextIndex);
      setCurrentBlockIndex(playlist[nextIndex].blockIndex);
      setPlaybackProgress((nextIndex / playlist.length) * 100);
    } else {
      setIsPlaying(false);
      setCurrentBlockIndex(-1);
      setPlaybackProgress(100);
    }
  };

  // Handle canplay - source has loaded successfully, transition complete
  const handleCanPlay = () => {
    isTransitioningRef.current = false;
  };

  // When track index changes, load the new src into the same video element
  useEffect(() => {
    if (!isPlaying || !videoRef.current || playlist.length === 0) return;
    const item = playlist[currentPrerollIndex];
    if (!item) return;
    const url = item.directUrl || getVideoUrl(item.preroll);
    if (url) {
      isTransitioningRef.current = true;
      videoRef.current.src = url;
      videoRef.current.load();
      videoRef.current.play().catch(() => {});
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentPrerollIndex, isPlaying]);

  // Handle video time update
  const handleTimeUpdate = () => {
    if (videoRef.current && playlist.length > 0) {
      const currentProgress = (currentPrerollIndex / playlist.length) * 100;
      const videoProgress = (videoRef.current.currentTime / videoRef.current.duration) * (100 / playlist.length);
      setPlaybackProgress(currentProgress + videoProgress);
    }
  };

  // eslint-disable-next-line no-unused-vars
  const toggleBlockExpanded = (index) => {
    const newExpanded = new Set(expandedBlocks);
    if (newExpanded.has(index)) {
      newExpanded.delete(index);
    } else {
      newExpanded.add(index);
    }
    setExpandedBlocks(newExpanded);
  };

  // Get category name
  // eslint-disable-next-line no-unused-vars
  const getCategoryName = (categoryId) => {
    const category = categories.find((c) => c.id === categoryId);
    return category?.name || 'Unknown Category';
  };

  // Get block icon
  // eslint-disable-next-line no-unused-vars
  const getBlockIcon = (type) => {
    const icons = {
      preroll: '',
      fixed: '',
      random: '',
      sequential: '',
      queue: '⏭️',
      sequence: '',
      separator: '┃',
    };
    return icons[type] || '';
  };

  // Get block color
  // eslint-disable-next-line no-unused-vars
  const getBlockColor = (type) => {
    const colors = {
      preroll: '#667eea',
      fixed: '#dc2626',
      random: '#f59e0b',
      sequential: '#10b981',
      nexup_trailers: '#e11d48',
      coming_soon_list: '#0891b2',
      dynamic_preroll: '#16a34a',
      queue: '#ec4899',
      sequence: '#8b5cf6',
      separator: '#6b7280',
    };
    return colors[type] || '#9ca3af';
  };

  // Format duration
  // eslint-disable-next-line no-unused-vars
  const formatDuration = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  if (!isOpen) return null;

  return (
    <div
      ref={overlayRef}
      className="nx-modal-overlay"
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        backgroundColor: 'rgba(0, 0, 0, 0.85)',
        zIndex: 10000,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: 'clamp(0.5rem, 4vw, 2rem)',
      }}
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      {/* Compact Video Player Overlay */}
      <div
        role="dialog"
        aria-modal="true"
        aria-labelledby="sequence-preview-title"
        style={{
          backgroundColor: 'var(--card-bg)',
          borderRadius: '12px',
          overflow: 'hidden',
          width: '100%',
          maxWidth: '900px',
          maxHeight: 'calc(100dvh - 1rem)',
          boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.5)',
          display: 'flex',
          flexDirection: 'column',
        }}
      >
        {/* Compact Header */}
        <div
          style={{
            padding: '1rem 1.5rem',
            borderBottom: '1px solid var(--border-color)',
            backgroundColor: 'var(--bg-color)',
            display: 'flex',
            // The notices below take a full row of their own (flexBasis 100%),
            // which only happens when the header is allowed to wrap.
            flexWrap: 'wrap',
            justifyContent: 'space-between',
            alignItems: 'center',
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <span style={{ display: 'flex', alignItems: 'center', color: 'var(--button-bg)' }}><Film size={22} /></span>
            <div style={{ minWidth: 0 }}>
              <h3 id="sequence-preview-title" style={{ margin: 0, fontSize: '1.1rem', color: 'var(--text-color)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {sequenceName}
              </h3>
              <p style={{ margin: 0, fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
                {playlist.length} preroll{playlist.length !== 1 ? 's' : ''} • {blocks.length} block{blocks.length !== 1 ? 's' : ''}
                {skippedBlocks.length > 0 && (
                  <span style={{ color: '#c2660a' }}>
                    {' '}• {skippedBlocks.length} skipped
                  </span>
                )}
              </p>
            </div>
          </div>
          {skippedBlocks.length > 0 && (
            <div
              role="status"
              style={{
                flexBasis: '100%', order: 99, marginTop: '0.6rem',
                padding: '0.55rem 0.75rem', borderRadius: '6px',
                border: '1px solid rgba(194,102,10,0.45)',
                background: 'rgba(194,102,10,0.10)',
                color: 'var(--text-color)', fontSize: '0.83rem', lineHeight: 1.45,
              }}
            >
              <strong>Not everything in this sequence can play.</strong>{' '}
              {skippedBlocks.map((b, i) => (
                <span key={b.index}>
                  {i > 0 ? ', ' : ''}block {b.index + 1} ({b.label})
                </span>
              ))}{' '}
              {skippedBlocks.length === 1 ? 'has' : 'have'} nothing to play, so{' '}
              {skippedBlocks.length === 1 ? 'it is' : 'they are'} left out of this preview.
              {skippedBlocks.some(b => b.type === 'nexup_trailers') &&
                ' NeX-Up trailer blocks need trailers downloaded first - check NeX-Up > Connections.'}
            </div>
          )}
          {sequenceGenres.length > 0 && (
            <label style={{
              flexBasis: '100%', order: 98, marginTop: '0.6rem',
              display: 'flex', alignItems: 'center', gap: '0.5rem', flexWrap: 'wrap',
              fontSize: '0.83rem', color: 'var(--text-secondary)',
            }}>
              Preview as
              <select
                value={previewGenre}
                onChange={(event) => setPreviewGenre(event.target.value)}
                style={{
                  padding: '4px 8px', borderRadius: '6px', border: '1px solid var(--border-color)',
                  background: 'var(--input-bg)', color: 'var(--text-color)', fontSize: '0.83rem',
                }}
              >
                <option value="">Plex (genre unknown)</option>
                {sequenceGenres.map(genre => <option key={genre} value={genre}>A {genre} movie on Jellyfin or Emby</option>)}
              </select>
            </label>
          )}
          {hasAudioRules && <label style={{ fontSize: 13, display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }}>
            Simulate stored audio
            <select aria-label="Preview audio format" value={previewAudio} onChange={event => setPreviewAudio(event.target.value)}>
              <option value="">Unknown / Plex</option>
              {AUDIO_FORMATS.map(([key, label]) => <option key={key} value={key}>{label} (one stored track)</option>)}
            </select>
          </label>}
          {conditionNotes.length > 0 && (
            <div
              role="status"
              style={{
                flexBasis: '100%', order: 99, marginTop: '0.6rem',
                padding: '0.55rem 0.75rem', borderRadius: '6px',
                border: '1px solid var(--border-color)',
                background: 'var(--hover-bg)',
                color: 'var(--text-color)', fontSize: '0.83rem', lineHeight: 1.45,
              }}
            >
              <strong>
                Conditions, checked as if {previewGenre ? `a ${previewGenre} movie` : 'a movie'} were starting now
                {sequenceGenres.length > 0 && !previewGenre && !previewAudio ? ' with unknown genre, as on Plex' : ''}:
              </strong>
              {conditionNotes.map(note => (
                <div key={note.index}>
                  Block {note.index + 1} ({note.label}){' '}
                  {note.outcome === 'plays'
                    ? <>plays, because {describeCondition(note.condition)}.</>
                    : <>
                      {note.outcome === 'skipped' ? 'is skipped' : 'plays its alternative'}
                      {!previewGenre && !previewAudio && needsPlaybackInfo(note.condition)
                        ? ', because the required playback metadata is unknown, as on Plex.'
                        : <>{' '}because this is not true: {describeCondition(note.condition)}.</>}
                    </>}
                </div>
              ))}
            </div>
          )}
          <button
            type="button"
            onClick={onClose}
            style={{
              width: '32px',
              height: '32px',
              padding: 0,
              backgroundColor: 'transparent',
              color: 'var(--text-secondary)',
              border: 'none',
              borderRadius: '6px',
              cursor: 'pointer',
              fontSize: '1.25rem',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              transition: 'all 0.2s',
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.backgroundColor = 'var(--hover-bg)';
              e.currentTarget.style.color = 'var(--text-color)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = 'transparent';
              e.currentTarget.style.color = 'var(--text-secondary)';
            }}
            aria-label="Close sequence preview"
            title="Close"
          >
            <X size={20} aria-hidden="true" />
          </button>
        </div>

        {/* Video Player */}
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0 }}>
          {blocks.length === 0 ? (
            <div
              style={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                padding: '3rem 2rem',
                textAlign: 'center',
                minHeight: 'min(400px, 55dvh)',
              }}
            >
              <div style={{ marginBottom: '1rem', opacity: 0.5, display: 'flex', justifyContent: 'center' }}><Inbox size={56} /></div>
              <h3 style={{ color: 'var(--text-color)', marginBottom: '0.5rem', margin: 0 }}>
                No Blocks in Sequence
              </h3>
              <p style={{ color: 'var(--text-secondary)', margin: '0.5rem 0 0 0' }}>
                Add blocks to your sequence to preview playback.
              </p>
            </div>
          ) : !isPlaying ? (
            <div
              style={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                padding: '3rem 2rem',
                textAlign: 'center',
                minHeight: '400px',
                backgroundColor: '#000',
              }}
            >
              <div style={{ fontSize: '4rem', marginBottom: '1rem' }}>▶️</div>
              <h3 style={{ color: '#fff', marginBottom: '1rem', margin: '0 0 1rem 0' }}>
                Ready to Play
              </h3>
              <p style={{ color: 'rgba(255, 255, 255, 0.7)', margin: '0 0 1.5rem 0', maxWidth: '400px' }}>
                Click the play button below to start the sequence preview. Random category blocks will select a random preroll.
              </p>
              <button
                onClick={startPlayback}
                disabled={playlist.length === 0}
                style={{
                  padding: '0.875rem 2rem',
                  backgroundColor: '#667eea',
                  color: 'white',
                  border: 'none',
                  borderRadius: '8px',
                  cursor: playlist.length === 0 ? 'not-allowed' : 'pointer',
                  fontSize: '1.05rem',
                  fontWeight: 600,
                  opacity: playlist.length === 0 ? 0.5 : 1,
                  display: 'flex',
                  alignItems: 'center',
                  gap: '0.5rem',
                  transition: 'all 0.2s',
                }}
                onMouseEnter={(e) => {
                  if (playlist.length > 0) {
                    e.currentTarget.style.backgroundColor = '#5568d3';
                    e.currentTarget.style.transform = 'translateY(-2px)';
                  }
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.backgroundColor = '#667eea';
                  e.currentTarget.style.transform = 'translateY(0)';
                }}
              >
                ▶ Play Sequence
              </button>
            </div>
          ) : (
            <>
              <video
                ref={videoRef}
                autoPlay
                controls
                aria-label={`Sequence preview for ${sequenceName}`}
                onEnded={handleVideoEnded}
                onError={handleVideoError}
                onCanPlay={handleCanPlay}
                onTimeUpdate={handleTimeUpdate}
                style={{
                  width: '100%',
                  height: 'auto',
                  maxHeight: '70vh',
                  backgroundColor: '#000',
                  display: 'block',
                }}
              />
              
              {/* Playback Progress Bar */}
              <div
                style={{
                  width: '100%',
                  height: '3px',
                  backgroundColor: 'rgba(102, 126, 234, 0.2)',
                }}
              >
                <div
                  style={{
                    width: `${playbackProgress}%`,
                    height: '100%',
                    backgroundColor: '#667eea',
                    transition: 'width 0.1s linear',
                  }}
                />
              </div>

              {/* Now Playing Info */}
              <div
                style={{
                  padding: '1rem 1.5rem',
                  backgroundColor: 'var(--bg-color)',
                  borderTop: '1px solid var(--border-color)',
                }}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.75rem' }}>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', marginBottom: '0.25rem' }}>
                      Now Playing • Block {currentBlockIndex + 1}
                    </div>
                    <div 
                      style={{ 
                        fontSize: '0.95rem', 
                        fontWeight: 600, 
                        color: 'var(--text-color)',
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap'
                      }}
                      title={playlist[currentPrerollIndex]?.title || playlist[currentPrerollIndex]?.preroll?.display_name || playlist[currentPrerollIndex]?.preroll?.filename}
                    >
                      {playlist[currentPrerollIndex]?.title || playlist[currentPrerollIndex]?.preroll?.display_name || playlist[currentPrerollIndex]?.preroll?.filename}
                    </div>
                  </div>
                  <div style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', marginLeft: '1rem', flexShrink: 0 }}>
                    {currentPrerollIndex + 1} / {playlist.length}
                  </div>
                </div>
                
                {/* Stop Button */}
                <button
                  onClick={stopPlayback}
                  style={{
                    width: '100%',
                    padding: '0.625rem',
                    backgroundColor: 'var(--bg-color)',
                    color: 'var(--text-color)',
                    border: '1px solid var(--border-color)',
                    borderRadius: '6px',
                    cursor: 'pointer',
                    fontSize: '0.9rem',
                    fontWeight: 600,
                    transition: 'all 0.2s',
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.backgroundColor = '#ef4444';
                    e.currentTarget.style.borderColor = '#ef4444';
                    e.currentTarget.style.color = 'white';
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.backgroundColor = 'var(--bg-color)';
                    e.currentTarget.style.borderColor = 'var(--border-color)';
                    e.currentTarget.style.color = 'var(--text-color)';
                  }}
                >
                  ⏹ Stop Playback
                </button>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default SequencePreviewModal;
